#!/usr/bin/env python3
"""Read existing reports/queue; write publication summaries only, with no model fits."""
from pathlib import Path
import csv,datetime,hashlib,json,sqlite3
ROOT=Path(__file__).resolve().parents[2]
OUT=Path(__file__).resolve().parent
read=lambda p:json.loads(p.read_text())
rows=lambda p:list(csv.DictReader(p.open(newline='')))
now=datetime.datetime.now(datetime.timezone.utc).isoformat()
progress=read(ROOT/'reports/progress.json')
if not progress.get('snapshot_ready'):raise SystemExit('Canonical report refresh is still in progress')
c=sqlite3.connect(f'file:{ROOT}/queue.sqlite3?mode=ro',uri=True)
c.row_factory=sqlite3.Row
counts={r['status']:r['n'] for r in c.execute('select status,count(*) n from jobs group by status')}
boot=(Path('/proc/sys/kernel/random/boot_id')).read_text().strip()
incomplete=[]
for r in c.execute("select id,status from jobs where status!='completed' order by ordinal"):
 p=ROOT/'jobs'/r['id']/'result.json'
 if p.exists():
  q=read(p)
  incomplete.append({'job_id':r['id'],'queue_status':r['status'],'result_status':q.get('status'),'result_complete':q.get('complete'),'testing_only':q.get('testing_only'),'counted_as_completed_in_publication':False})
source=rows(ROOT/'reports/source_accuracy_summary.csv')
nulls=rows(ROOT/'reports/permutation_null_summary.csv')
material=rows(ROOT/'reports/material_PRED_summary.csv')
methods=[('baseline','svm_alpha_snv'),('baseline','lda_alpha_raw_snv'),('baseline','lda_joint_both_snv'),('selection','alpha_snv'),('selection','joint_both_snv'),('selection','joint_nraw_asnv'),('retain_drop','joint_both_snv'),('spacing','alpha_gap4_k62_c2'),('coverage','uniform_k62')]
selected=[]
for family,variant in methods:
 selected += [r for r in source if r['family']==family and r['variant']==variant and r['mc_draws']=='20']
hashes=read(OUT/'frozen_hashes_verified.json')
summary={'schema':'ml-completed-publication-summary-v1','captured_utc':now,'scope':'Old ML background study only, independent from chemistry','study_complete':False,'training_snapshot_state':'No current-boot canonical training workers; saved supervisor status is from the previous boot. Publication precedes authorized resume.','current_boot_id':boot,'queue_counts':counts,'manifest_jobs':sum(counts.values()),'queue_completed_fraction':counts.get('completed',0)/sum(counts.values()),'published_completed_job_count':counts.get('completed',0),'incomplete_jobs_excluded_from_completed_archive':counts.get('queued',0)+counts.get('running',0),'uncommitted_complete_result_files':incomplete,'canonical_report_progress':progress,'canonical_report_count_distinction':'The canonical report scans valid result files, not SQLite completion. Two complete files from stale running attempts are included in its validated-file count but excluded from the completed archive; their source repeat lacks all five folds and cannot contribute a reported method-level complete-repeat estimate.','selected_descriptive_MC20_rows':selected,'permutation_null_rows':nulls,'fixed_PRED_material_rows':material,'all_source_method_groups':len(source),'all_seven_frozen_files_match':hashes['all_seven_match'],'protocol_sha256':hashes['protocol_sha256'],'authorized_cumulative_cpu_seconds':1360000,'new_budget_authorization':False,'new_model_fits_for_summary':0,'sources':['reports/progress.json','reports/summary_manifest.json','reports/source_accuracy_summary.csv','reports/permutation_null_summary.csv','reports/material_PRED_summary.csv','reports/repeat_completion.csv','reports/summary_zh.md','queue.sqlite3 (read-only consistent snapshot; publication archive stores a backup)','protocol.json','RESOURCE_BUDGET_NOTE_zh.md'],'interpretation_limits':['Retrospective internal re-evaluation of the same 300 source specimens; repeated splits are not independent new specimens.','Method figures use only full five-fold source repeats. Confidence intervals are conditional on existing predictions, stratified by class and clustered by physical ID, with 5,000 bootstrap draws; no refitting or multiplicity correction.','Methods/MC levels have differing completed repeat counts; rows are descriptive and do not establish a statistically significant winner.','Label permutation and fixed-role material tasks have different targets and must remain separate from real-source OOF accuracy.','Fixed PRED specimens recur across material fits; repeated perfect predictions do not demonstrate external validation.','No same-ID quantified chemistry or validated reference bands; no chemical mechanism inference.','Completion is bounded by the original cumulative CPU cap and cloud lifecycle; no claim that the whole study is finished.']}
(OUT/'research_summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
def pct(x):return f'{100*float(x):.2f}%'
lines=['# Old ML background study — completed-results publication','',f'Captured {now}. This study is independent of the chemistry computation.','',f'The queue contains **{counts["completed"]:,} completed jobs of {sum(counts.values()):,}** ({100*summary["queue_completed_fraction"]:.2f}%). Another {counts["queued"]:,} jobs are queued and {counts["running"]} were marked running on the previous boot; all {summary["incomplete_jobs_excluded_from_completed_archive"]:,} unfinished jobs are excluded from the completed-results archive. The study is still incomplete. At capture, canonical training was stopped after the cloud reboot; the saved report supervisor state is from the previous boot. Publication precedes the authorized resume.','',f'The canonical report was refreshed at {progress["updated_utc"]} without new model fitting. It validated {progress["validated_complete_result_jobs"]:,} non-testing complete result files with {progress["invalid_result_jobs"]} invalid and {progress["excluded_testing_results"]} testing exclusions. This is two more than SQLite-completed jobs because two previous-boot running attempts had written complete result files before queue commitment. Those two are excluded from the completed archive; their incomplete five-fold repeat is excluded from method-level source estimates. Reports are preserved as generated, with this distinction explicit.','','## Current descriptive findings','',f'There are {len(source)} reportable source method/MC groups, {progress["complete_source_repeats"]:,} complete source repeats, {progress["complete_null_repeats"]:,} complete label-permutation repeats, and {progress["material_fixed_role_fits"]:,} fixed-role material fits. The source population remains the same 300 physical specimens.','', 'Selected predeclared MC20 comparisons (or methods without an MC parameter):','', '| Family / variant | Complete repeats | Mean source accuracy | Conditional 95% interval |','|---|---:|---:|---:|']
for r in selected:lines.append(f'| {r["family"]} / {r["variant"]} | {r["complete_repeats"]} | {pct(r["mean_accuracy"])} | {pct(r["accuracy_ci95_low"])}–{pct(r["accuracy_ci95_high"])} |')
lines+=['','The alpha-SNV selection and retain/drop workflows currently give about 93% mean internal source accuracy. Several full-spectrum LDA workflows give about 91%. These are descriptive comparisons over differing completed repeat sets; the reports do not establish a statistically significant winner or independent information from refractive index. MC100 and MC500 results remain separate sensitivity levels with fewer repeats.','','Label-permutation controls remain near the five-class chance level: '+', '.join(f'{r["variant"]} {pct(r["mean_accuracy"])} ({r["complete_repeats"]} repeats)' for r in nulls)+'. They are a separate null target.','','Fixed-PRED material results are reported separately: '+', '.join(f'{r["variant"]} {pct(r["mean_accuracy"])} on {r["unique_physical_ids"]} unique specimens' for r in material)+'. Repeated fits reuse these same fixed PRED specimens.','','## Evidence and interpretation','','All seven frozen source/input files match the pre-recovery SHA-256 checks; the current protocol SHA-256 is `'+hashes['protocol_sha256']+'`. The cumulative authorization remains **1,360,000 CPU seconds**; publication adds no authorization. Older text mentioning an initial 90,000-second budget is historical and is superseded by the recorded authorizations and current protocol.','','The archive preserves completed job results, predictions, selections, fitted artifacts or verified lossless reconstruction recipes, diagnostic archives, shared exact input NPZ and worker, reports, source/protocol, consistent SQLite snapshot, and file/shard manifests. `MODEL_ARTIFACT_CODEC_README.txt` explains restoration without training. Incomplete jobs remain labelled in queue provenance and are not counted as completed evidence.','','Source intervals are conditional on trained outer-test predictions: per-record mean correctness is bootstrapped within class by physical ID (5,000 draws, seed 20261110), retaining repeated predictions. They do not include model refitting, multiple-comparison correction, independent specimens, or external/cross-batch generalization. Full five-fold source repeats alone enter the method summaries. Material and permutation targets must not be pooled with source OOF accuracy. Chemical mechanism inference remains blocked by absent same-ID quantitative chemistry and validated reference bands.','','Primary report: `reports/summary_zh.md`; numerical evidence: `reports/source_accuracy_summary.csv`, `reports/permutation_null_summary.csv`, `reports/material_PRED_summary.csv`, `reports/repeat_completion.csv`; publication counts/hashes: `research_summary.json` and `frozen_hashes_verified.json`.']
(OUT/'RESEARCH_SUMMARY.md').write_text('\n'.join(lines)+'\n')
print(json.dumps({'summary':str(OUT/'RESEARCH_SUMMARY.md'),'queue_counts':counts,'validated_result_files':progress['validated_complete_result_jobs'],'all_seven_match':hashes['all_seven_match']},ensure_ascii=False))
